${pagingTop}
SELECT
  b.think_pocket_package_idx, b.think_pocket_package_loan_idx, a.think_pocket_package_subject, b.request_name, b.phone,
  a.quantity, a.loan_count, a.grade, b.phone, b.request_content,
  TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date,
  b.request_status, b.return_yn, b.add_id, b.add_date, a.category,
  b.loan_place, b.user_key, b.homepage_name
FROM
    THINK_POCKET_PACKAGE a, THINK_POCKET_PACKAGE_LOAN b
WHERE
    a.think_pocket_package_idx = b.think_pocket_package_idx
  AND a.homepage_id = #{homepage_id}

  AND	${search_type} LIKE '%'||#{search_text}||'%'



    AND	return_yn = #{return_yn}
    AND	request_status = '2'


    AND	request_status = #{request_status}



