SELECT NVL(MAX(think_pocket_package_loan_idx), 0) + 1 FROM THINK_POCKET_PACKAGE_LOAN
INSERT INTO THINK_POCKET_PACKAGE_LOAN ( think_pocket_package_idx, think_pocket_package_loan_idx, request_name, loan_start_date, loan_end_date, phone, request_content, request_status, return_yn, add_id, add_date, loan_place, user_key, homepage_id, homepage_name, add_ip
) VALUES ( #{think_pocket_package_idx}, #{think_pocket_package_loan_idx}, #{request_name}, #{loan_start_date}, #{loan_end_date}, #{phone},#{request_content}, #{request_status}, 'N', #{add_id}, SYSDATE, #{loan_place}, #{user_key}, #{homepage_id}, #{homepage_name}, #{add_ip} )

