mapper.select:
SELECT b.think_pocket_package_idx, b.think_pocket_package_loan_idx, a.think_pocket_package_subject, b.request_name, a.quantity, a.loan_count, TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date, b.phone, b.request_content, b.request_status, b.return_yn, b.add_id, b.add_date, a.category, b.loan_place FROM THINK_POCKET_PACKAGE a, THINK_POCKET_PACKAGE_LOAN b WHERE a.think_pocket_package_idx = b.think_pocket_package_idx AND a.homepage_id = #{homepage_id}
AND b.add_id = #{add_id}
AND REGEXP_LIKE(category, REPLACE(#{category}, ',', '|'))
ORDER BY b.think_pocket_package_loan_idx DESC
